const today=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
let lang='ro', catalog, categories, quotes, settings, lines=[], editingQuoteId=null, quoteGroups=[];
function loadState(){try{catalog=JSON.parse(localStorage.getItem('dp_catalog'))||initialCatalog.map(x=>({...x,active:true}));}catch{catalog=initialCatalog.map(x=>({...x,active:true}))}
try{categories=JSON.parse(localStorage.getItem('dp_categories'))||[...new Set(catalog.map(x=>x.category))];}catch{categories=[...new Set(catalog.map(x=>x.category))]}
try{quotes=JSON.parse(localStorage.getItem('dp_quotes'))||[]}catch{quotes=[]}
try{quoteGroups=JSON.parse(localStorage.getItem('dp_groups'))||[]}catch{quoteGroups=[]}quoteGroups.forEach(g=>{if(typeof g.collapsed!=='boolean')g.collapsed=true;if(!Number.isFinite(Number(g.order)))g.order=Date.now()})
try{settings=JSON.parse(localStorage.getItem('dp_settings'))||{bizName:'',bizPhone:'',bizInstagram:'',bizTikTok:'',bizWeb:'',bizAddress:'',terms:'Prețurile sunt valabile pentru lucrările și cantitățile indicate în deviz. / Цены действительны для указанных в смете работ и объёмов.',accentColor:'#167347',currency:'MDL',signatureOn:true,signature:''}}catch{settings={accentColor:'#167347',currency:'MDL',signatureOn:true}}
}
function persist(){localStorage.setItem('dp_catalog',JSON.stringify(catalog));localStorage.setItem('dp_categories',JSON.stringify(categories));localStorage.setItem('dp_quotes',JSON.stringify(quotes));localStorage.setItem('dp_groups',JSON.stringify(quoteGroups));localStorage.setItem('dp_settings',JSON.stringify(settings));mirrorStateToIndexedDB()}
function t(ro,ru){return lang==='ro'?ro:ru}
function setLang(l){lang=l;document.documentElement.lang=l;$('roBtn').classList.toggle('active',l==='ro');$('ruBtn').classList.toggle('active',l==='ru');document.querySelectorAll('[data-ro]').forEach(el=>{const val=el.getAttribute('data-'+l);if(val!==null&&el.tagName!=='INPUT'&&el.tagName!=='TEXTAREA'&&el.tagName!=='SELECT'&&el.tagName!=='OPTION')el.textContent=val});document.querySelectorAll('[data-ro-placeholder]').forEach(el=>{const val=el.getAttribute('data-'+l+'-placeholder');if(val!==null)el.placeholder=val});document.querySelectorAll('select option').forEach(el=>{if(el.dataset.ro!==undefined||el.dataset.ru!==undefined){el.textContent=el.getAttribute('data-'+l)||el.textContent}else if(el.textContent.includes(' / ')){const parts=el.textContent.split(' / ');if(parts.length===2)el.textContent=parts[l==='ro'?0:1]}});if($('subtitle'))$('subtitle').textContent=t('Devize de construcții · offline · adaptivă','Сметы на строительство · офлайн · адаптивная');document.querySelectorAll('#nav button').forEach(b=>{const tip=b.getAttribute('data-tip-'+l)||b.getAttribute('data-tip-ro')||'';b.dataset.tip=tip;b.setAttribute('aria-label',tip);b.title=""});const gn=$('newGroupName');if(gn)gn.placeholder=t('Numele grupului, ex. Casa familiei','Название группы, например Дом семьи');refreshAll();if(typeof dpRefreshQuoteMeasurements==='function')dpRefreshQuoteMeasurements();updateTransferOptions();try{if(typeof renderLedger==='function')renderLedger();if(typeof renderPayments==='function'&&document.getElementById('dpPaymentEvents'))renderPayments();if(typeof renderWorkReports==='function'&&document.getElementById('dpWorkReportsList'))renderWorkReports();if(typeof renderReceiptSettings==='function'&&document.getElementById('dpDefaultReceiptFields'))renderReceiptSettings()}catch(e){console.warn('Language refresh:',e)}}
function money(n){return (Number(n)||0).toLocaleString('ro-RO',{minimumFractionDigits:2,maximumFractionDigits:2})+' '+(settings.currency||'MDL')}
function norm(s){return String(s??'').toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ș|ş/g,'s').replace(/ț|ţ/g,'t').replace(/ă|â/g,'a').replace(/î/g,'i').replace(/[^a-z0-9а-яё]+/gi,' ').trim()}
function formatDate(v){if(!v)return '';const d=new Date(v+'T12:00:00');if(isNaN(d))return v;const f=settings.dateFormat||'long';if(f==='dd.mm.yyyy')return String(d.getDate()).padStart(2,'0')+'.'+String(d.getMonth()+1).padStart(2,'0')+'.'+d.getFullYear();if(f==='dd/mm/yyyy')return String(d.getDate()).padStart(2,'0')+'/'+String(d.getMonth()+1).padStart(2,'0')+'/'+d.getFullYear();if(f==='yyyy-mm-dd')return v;return d.toLocaleDateString('ro-RO',{day:'numeric',month:'long',year:'numeric'})}
function toggleExpiryFields(){ $('validUntil').disabled=!$('validUntilOn').checked; $('discountUntil').disabled=!$('discountUntilOn').checked; renderPreview(); }

function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
